/**
 * Simple Module Bundler for Chrome Extension Content Scripts
 * Concatenates ES6 modules into a single file, removing import/export statements
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PROJECT_ROOT = path.join(__dirname, '..');
const SRC_DIR = path.join(PROJECT_ROOT, 'src', 'content');
const OUTPUT_FILE = path.join(PROJECT_ROOT, 'Output', 'src', 'content', 'content-bundle.js');

// Order matters - utilities first, then features, then main
const MODULES_IN_ORDER = [
  'utils/storage-utils.js',
  'utils/dom-utils.js',
  'features/tts.js',
  'features/dyslexia.js',
  'features/text-customization.js',
  'features/reading-guide.js',
  'features/focus-mode.js',
  'features/screen-overlay.js',
  'features/stt.js',
  'lms/canvas.js',
  'lms/moodle.js',
  'lms/google-classroom.js',
  'index.js'
];

function stripImportsExports(code) {
  // Remove import statements
  code = code.replace(/^import\s+.*?from\s+['"].*?['"];?\s*$/gm, '');
  code = code.replace(/^import\s+['"].*?['"];?\s*$/gm, '');

  // Remove export keywords but keep the declarations
  code = code.replace(/^export\s+async\s+function\s+/gm, 'async function ');
  code = code.replace(/^export\s+function\s+/gm, 'function ');
  code = code.replace(/^export\s+const\s+/gm, 'const ');
  code = code.replace(/^export\s+let\s+/gm, 'let ');
  code = code.replace(/^export\s+var\s+/gm, 'var ');
  code = code.replace(/^export\s+class\s+/gm, 'class ');
  code = code.replace(/^export\s+default\s+/gm, '');
  code = code.replace(/^export\s+\{[^}]*\};?\s*$/gm, '');

  return code;
}

function bundleModules() {
  console.log('🔗 Bundling content script modules...\n');

  let bundledCode = '';

  // Add header
  bundledCode += '/**\n';
  bundledCode += ' * AssisT Extension - Content Script Bundle\n';
  bundledCode += ' * Auto-generated from modular source files\n';
  bundledCode += ' * DO NOT EDIT THIS FILE DIRECTLY - Edit source files in src/content/\n';
  bundledCode += ' */\n\n';

  // Add IIFE wrapper to avoid global scope pollution
  bundledCode += '(function() {\n';
  bundledCode += '  "use strict";\n\n';

  // Process each module
  for (const modulePath of MODULES_IN_ORDER) {
    const fullPath = path.join(SRC_DIR, modulePath);

    if (!fs.existsSync(fullPath)) {
      console.warn(`⚠️  Warning: ${modulePath} not found, skipping`);
      continue;
    }

    console.log(`  ✓ Adding: ${modulePath}`);

    let code = fs.readFileSync(fullPath, 'utf8');

    // Strip import/export
    code = stripImportsExports(code);

    // Add module comment
    bundledCode += `  // ========================================\n`;
    bundledCode += `  // Module: ${modulePath}\n`;
    bundledCode += `  // ========================================\n\n`;

    // Indent the code (2 spaces for IIFE)
    code = code.split('\n').map(line => '  ' + line).join('\n');

    bundledCode += code + '\n\n';
  }

  // Close IIFE
  bundledCode += '})();\n';

  // Ensure output directory exists
  const outputDir = path.dirname(OUTPUT_FILE);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write bundled file
  fs.writeFileSync(OUTPUT_FILE, bundledCode, 'utf8');

  const stats = fs.statSync(OUTPUT_FILE);
  const sizeKB = (stats.size / 1024).toFixed(2);

  console.log(`\n✅ Bundle created: ${path.relative(PROJECT_ROOT, OUTPUT_FILE)}`);
  console.log(`   Size: ${sizeKB} KB`);
  console.log(`   Modules: ${MODULES_IN_ORDER.length}`);
}

// Run bundler
try {
  bundleModules();
} catch (error) {
  console.error('❌ Bundling failed:', error.message);
  process.exit(1);
}
